let actionButton=status==='yes'&&selected?'<button class="g-btn" type="button" id="g-proceed" '+(selected.target!=='EDIT'&&checked.size!==r.checks.length?'disabled':'')+'>'+(selected.target==='OUTCOME'?'Open referral and follow-up':selected.target==='EDIT'?'Change originating answer':'Proceed to next permitted step')+'</button>':'';
