let noInfo=status==='no'?'<section class="g-soft" aria-label="Actions while unresolved"><h3>What should happen now? Choose an action</h3><p>The issue is still open. Select an action below for specific guidance; selecting it does not mark the legal issue resolved.</p><div class="g-status"><button type="button" class="g-toggle" data-help-action="request" aria-pressed="'+(followupDetail==='request')+'">Request clarification / correction</button><button type="button" class="g-toggle" data-help-action="verify" aria-pressed="'+(followupDetail==='verify')+'">Verify records</button><button type="button" class="g-toggle" data-help-action="escalate" aria-pressed="'+(followupDetail==='escalate')+'">Seek competent review</button></div>'+(followupDetail&&['request','verify','escalate'].includes(followupDetail)?'<div class="g-guidance-result" role="status"><strong>Suggested action:</strong> '+safe(guide[{request:0,verify:1,escalate:2}[followupDetail]])+'<p class="g-mini">Suggested record: '+safe(guide[3])+'. Prepare any real document only through an authorised process.</p></div>':'<p class="g-mini">Choose one action above to see what to do next.</p>')+'<h3>Track the steps you plan to address</h3>'+r.checks.map((c,i)=>'<label class="g-check"><input type="checkbox" data-work-step="'+i+'" '+(workSteps.has(i)?'checked':'')+'><span>'+safe(c)+'</span></label>').join('')+'<p class="g-mini" id="g-work-progress">'+workSteps.size+' of '+r.checks.length+' actions noted for follow-up (not proof of legal completion).</p><button class="g-btn secondary" type="button" id="g-reassess">Reassess this same issue</button></section>':'';
let unsureInfo=status==='unsure'?'<section class="g-soft" aria-label="Verification of uncertainty"><h3>Not sure — identify what needs verification</h3><p>You do not have to guess. Select each unresolved question, then choose an action. No statutory step will be advanced merely because an uncertainty is noted.</p>'+r.checks.map((c,i)=>'<label class="g-check"><input type="checkbox" data-uncertain-step="'+i+'" '+(uncertainSteps.has(i)?'checked':'')+'><span>'+safe(c)+'</span></label>').join('')+'<div class="g-button-row"><button class="g-btn secondary" type="button" id="g-show-verification" '+(!uncertainSteps.size?'disabled':'')+'>How can I verify this?</button><button class="g-btn secondary" type="button" id="g-record-unknown">Record as unresolved / seek review</button></div>'+(followupDetail==='uncertainty-verify'?'<div class="g-guidance-result" role="status"><strong>Points to verify:</strong><ul>'+[...uncertainSteps].sort((a,b)=>a-b).map(i=>'<li>'+safe(r.checks[i])+'</li>').join('')+'</ul><p><strong>Review the source:</strong> '+safe(guide[1])+'</p><p><strong>If still unclear:</strong> '+safe(guide[2])+'</p><p class="g-mini">Suggested record: '+safe(guide[3])+'.</p></div>':'')+(followupDetail==='uncertainty-hold'?'<div class="g-guidance-result" role="status"><strong>Unresolved review route:</strong> '+safe(guide[2])+'<p>Keep this stage open. Do not infer missing facts or treat the issue as resolved.</p><p class="g-mini">Suggested record: '+safe(guide[3])+'.</p></div>':'')+'<div class="g-button-row"><button class="g-btn secondary" id="g-reassess" type="button">Reassess this same issue</button></div></section>':'';
let initialInfo=status===''?'<div class="g-soft"><h3>Select the actual status of this review</h3><p><strong>Yes:</strong> record the verified procedural route and confirm safeguards. <strong>No:</strong> choose and track corrective actions. <strong>Not sure:</strong> identify missing information or request independent review.</p></div>':'';

$('g-body').innerHTML='<h2>'+safe(q.prompt)+'</h2><p>Recorded procedural answer: <strong>'+safe(res.original.label)+'</strong></p><div class="g-review"><span class="g-label">Review and correction · '+safe(stageLabel(q.id))+'</span><h3>'+safe(r.title)+'</h3><p class="g-review-note">'+safe(r.issue)+'</p></div><h3>Has this issue been resolved now?</h3><div class="g-status" role="group" aria-label="Resolution status"><button class="g-toggle" data-status="yes" aria-pressed="'+(status==='yes')+'">Yes</button><button class="g-toggle" data-status="no" aria-pressed="'+(status==='no')+'">No</button><button class="g-toggle" data-status="unsure" aria-pressed="'+(status==='unsure')+'">Not sure</button></div>'+initialInfo+noInfo+unsureInfo+optionBlock+checklist+'<div class="g-button-row">'+actionButton+'</div>'+(['no','unsure'].includes(status)?'<button class="g-btn secondary" id="g-review-followup" type="button">Plan the next review and responsible owner</button>':'')+changeAnswerForm(q);
